function EventsPage() {
  const cats = ['All', 'Children', 'Women', 'Community', 'Environment', 'Inclusion', 'Animal Welfare'];
  const [cat, setCat] = useState('All'); const [query, setQuery] = useState(''); const [limit, setLimit] = useState(8);
  const list = useMemo(() => publicEvents.filter(e => (cat === 'All' || e.category.toLowerCase().includes(cat.toLowerCase()) || (cat === 'Women' && e.category === 'Women & Girls') || (cat === 'Community' && e.category === 'Community Welfare') || (cat === 'Environment' && e.category === 'Environment & Animals') || (cat === 'Animal Welfare' && e.title === 'Feed a Dog')) && e.title.toLowerCase().includes(query.toLowerCase())), [cat, query]);
  return <PublicLayout><main className="page-enter">
    <section className="bg-[#f2e8da] px-5 py-16 md:px-9 md:py-24"><div className="mx-auto max-w-7xl"><Eyebrow>From the community</Eyebrow><h1 className="serif text-6xl leading-[1.04] text-[#4d241e] md:text-8xl">Shared moments.<br/><em className="text-[#788b6b]">Shared purpose.</em></h1><p className="mt-6 max-w-2xl text-lg leading-8 text-[#62554c]">Explore the initiatives and gatherings that bring our community together.</p></div></section>
    <section className="mx-auto max-w-7xl px-5 py-12 md:px-9 md:py-16"><div className="flex flex-col gap-5 md:flex-row md:items-end md:justify-between"><div><Eyebrow>Initiative archive</Eyebrow><h2 className="serif text-4xl text-[#4d241e]">Browse all gatherings</h2></div><label className="flex h-12 min-w-64 items-center gap-3 rounded-full border border-[#e2d6c8] bg-[#fffdf8] px-4"><Search size={17} className="text-[#7c6f63]"/><input aria-label="Search initiatives" className="w-full bg-transparent text-sm outline-none placeholder:text-[#978a7e]" placeholder="Search by name" value={query} onChange={e => setQuery(e.target.value)}/></label></div>
      <div className="my-7 flex gap-2 overflow-x-auto pb-2">{cats.map(item => <button key={item} type="button" onClick={() => { setCat(item); setLimit(8); }} className={`shrink-0 rounded-full px-4 py-2.5 text-sm transition-colors ${cat === item ? 'bg-[#51261f] text-white' : 'border border-[#e2d6c8] bg-[#fffdf8] text-[#62554c] hover:border-[#9a7060]'}`}>{item}</button>)}</div>
      {list.length ? <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{list.slice(0, limit).map((e, i) => <Link href={`/events/${e.id}`} key={e.id} className="group rounded-[1.7rem] border border-[#e8ddcf] bg-[#fffdf8] p-3 transition-all hover:-translate-y-1 hover:shadow-lg"><InitiativeArt title={e.title} category={e.category} index={i}/><div className="px-2 pb-2 pt-4"><div className="flex items-center justify-between gap-2"><span className="rounded-full bg-[#e9eee3] px-3 py-1.5 text-xs font-semibold text-[#566d50]">{e.category}</span><span className="rounded-full bg-[#f5eddf] px-2.5 py-1 text-[10px] text-[#816d58]">Details to be confirmed</span></div><h3 className="serif mt-3 min-h-14 text-2xl text-[#4d241e]">{e.title}</h3><p className="mt-2 text-xs leading-5 text-[#786b60]">Description · Details to be confirmed</p><div className="mt-3 space-y-1 border-t border-[#eee8df] pt-3 text-[11px] text-[#786b60]"><p>Date · Details to be confirmed</p><p>Location · Details to be confirmed</p></div><span className="mt-4 inline-flex items-center gap-2 text-sm font-bold text-primary">View Details <ArrowRight size={15} className="transition-transform group-hover:translate-x-1"/></span></div></Link>)}</div> : <div className="rounded-3xl border border-dashed border-[#d8cbbb] bg-[#f6f0e6] px-6 py-16 text-center"><Search className="mx-auto text-[#8a7868]"/><p className="serif mt-4 text-2xl text-[#4d241e]">No gatherings found</p><p className="mt-2 text-sm text-[#786b60]">Try a different name or category.</p></div>}
      {list.length > limit && <div className="mt-9 text-center"><Button tone="outline" onClick={() => setLimit(n => n + 8)}>Load more <ChevronDown size={16}/></Button></div>}
    </section>
  </main></PublicLayout>;
}
function EventDetailPage() {
  const { id } = useParams<{ id: string }>();
  const event = publicEvents.find(item => item.id === id);
  if (!event) return <NotFound/>;
  return <PublicLayout><main className="page-enter mx-auto min-h-[60vh] max-w-5xl px-5 py-16 md:px-9 md:py-24"><Link href="/events" className="inline-flex items-center gap-2 text-sm font-semibold text-[#70594a]"><ArrowLeft size={16}/> Back to gatherings</Link><div className="mt-9 rounded-[2rem] bg-[#f2e8da] p-5 md:p-10"><InitiativeArt title={event.title} category={event.category} index={0}/><div className="p-3 md:p-5"><span className="rounded-full bg-[#e0e8d8] px-4 py-2 text-xs font-semibold text-[#53664e]">{event.category}</span><span className="ml-2 rounded-full bg-[#fffaf2] px-4 py-2 text-xs font-semibold text-[#816d58]">Status · Details to be confirmed</span><h1 className="serif mt-6 text-5xl leading-tight text-[#4d241e] md:text-7xl">{event.title}</h1><p className="mt-5 max-w-2xl text-lg leading-8 text-[#62554c]">Event details to be confirmed.</p><div className="mt-9 grid gap-4 border-t border-[#ddcebc] pt-6 text-sm text-[#786b60] sm:grid-cols-3"><p>Date<br/><b className="mt-1 block font-semibold text-[#51473e]">Details to be confirmed</b></p><p>Location<br/><b className="mt-1 block font-semibold text-[#51473e]">Details to be confirmed</b></p><p>Details<br/><b className="mt-1 block font-semibold text-[#51473e]">Details to be confirmed</b></p></div></div></div></main></PublicLayout>;
}
function ContactPage() {
  const [sent, setSent] = useState(false); const [error, setError] = useState('');
  function submit(e: FormEvent<HTMLFormElement>) { e.preventDefault(); const form = e.currentTarget; if (!form.reportValidity()) { setError('Please complete the required fields.'); return; } setError(''); setSent(true); form.reset(); }
  return <PublicLayout><main className="page-enter">
    <section className="bg-[#f2e8da] px-5 py-16 md:px-9 md:py-24"><div className="mx-auto max-w-7xl"><Eyebrow>Get in touch</Eyebrow><h1 className="serif max-w-4xl text-6xl leading-[1.04] text-[#4d241e] md:text-8xl">A conversation<br/>can be a <em className="text-[#788b6b]">beginning.</em></h1><p className="mt-6 max-w-xl text-lg leading-8 text-[#62554c]">Want to volunteer, ask a question or learn more about our work? We would be glad to hear from you.</p></div></section>
    <section className="mx-auto grid max-w-7xl gap-10 px-5 py-14 md:grid-cols-[.8fr_1.2fr] md:px-9 md:py-20"><div className="space-y-4"><div className="rounded-3xl bg-[#e9eee3] p-6"><span className="grid h-10 w-10 place-items-center rounded-full bg-white text-[#5d7657]"><Phone size={19}/></span><h2 className="serif mt-5 text-2xl text-[#354737]">Call us</h2><a className="mt-2 block text-sm text-[#51614e]" href="tel:+919945363186">+91 9945363186</a></div><div className="rounded-3xl bg-[#f5ecdf] p-6"><span className="grid h-10 w-10 place-items-center rounded-full bg-white text-[#845247]"><Mail size={19}/></span><h2 className="serif mt-5 text-2xl text-[#4d241e]">Write to us</h2><a className="mt-2 block break-all text-sm text-[#70594a]" href="mailto:peopleforpassion@gmail.com">peopleforpassion@gmail.com</a></div><div className="rounded-3xl bg-[#f5ecdf] p-6"><h2 className="serif text-2xl text-[#4d241e]">Find our community</h2><p className="mt-3 text-sm leading-7 text-[#70594a]">Instagram · People for Passion<br/>Facebook · People4Passion</p><p className="mt-2 text-xs text-[#88796e]">Social profile links have not been provided.</p></div></div>
      <form onSubmit={submit} className="rounded-[2rem] border border-[#e7dccc] bg-[#fffdf8] p-6 md:p-9"><Eyebrow>Send a note</Eyebrow><h2 className="serif text-3xl text-[#4d241e]">How can we help?</h2>{sent && <div role="status" className="mt-5 rounded-xl bg-[#e9eee3] p-4 text-sm leading-6 text-[#41553e]"><b>Local demo confirmation.</b> Your form was not sent or stored; this message only confirms the interaction in this preview.</div>}{error && <p role="alert" className="mt-4 text-sm text-red-800">{error}</p>}<div className="mt-6 grid gap-4 sm:grid-cols-2">{[['Your name', 'name', 'text'], ['Email address', 'email', 'email'], ['Phone (optional)', 'phone', 'tel']].map(([label, name, type]) => <label key={name} className={`${name === 'phone' ? 'sm:col-span-2' : ''} text-sm font-medium text-[#574a40]`}>{label}<input required={name !== 'phone'} name={name} type={type} className="mt-2 w-full rounded-xl border border-[#dfd2c3] bg-[#fbf8f2] px-4 py-3 outline-none focus:border-[#855044]"/></label>)}<label className="sm:col-span-2 text-sm font-medium text-[#574a40]">Subject<input required name="subject" type="text" className="mt-2 w-full rounded-xl border border-[#dfd2c3] bg-[#fbf8f2] px-4 py-3 outline-none focus:border-[#855044]"/></label><label className="sm:col-span-2 text-sm font-medium text-[#574a40]">What would you like to talk about?<textarea required name="message" rows={5} className="mt-2 w-full resize-y rounded-xl border border-[#dfd2c3] bg-[#fbf8f2] px-4 py-3 outline-none focus:border-[#855044]"/></label></div><Button type="submit" className="mt-6">Send message <ArrowRight size={16}/></Button></form>
    </section>
  </main></PublicLayout>;
}

type Role = 'Super Admin' | 'Admin' | 'Volunteer-Staff';
type Permission = 'dashboard.view' | 'beneficiary.view' | 'beneficiary.create' | 'beneficiary.edit' | 'beneficiary.delete' | 'program.view' | 'program.create' | 'program.edit' | 'event.view' | 'event.create' | 'event.edit' | 'volunteer.manage' | 'reports.view' | 'user.manage' | 'settings.manage';
const permissionMap: Record<Role, Permission[]> = {
  'Super Admin': ['dashboard.view','beneficiary.view','beneficiary.create','beneficiary.edit','beneficiary.delete','program.view','program.create','program.edit','event.view','event.create','event.edit','volunteer.manage','reports.view','user.manage','settings.manage'],
  Admin: ['dashboard.view','beneficiary.view','beneficiary.create','beneficiary.edit','beneficiary.delete','program.view','program.create','program.edit','event.view','event.create','event.edit','reports.view'],
  'Volunteer-Staff': ['dashboard.view','beneficiary.view','beneficiary.create','beneficiary.edit','program.view'],
};
const sectionPermissions: Record<string, Permission> = { dashboard: 'dashboard.view', beneficiaries: 'beneficiary.view', programs: 'program.view', events: 'event.view', volunteers: 'volunteer.manage', users: 'user.manage', reports: 'reports.view', settings: 'settings.manage' };
function hasPermission(role: Role, permission: Permission) { return permissionMap[role].includes(permission); }
function canAccessSection(role: Role, section: string) { const permission = sectionPermissions[section]; return permission ? hasPermission(role, permission) : false; }
function roleLabel(role: Role) { return role === 'Volunteer-Staff' ? 'Volunteer / Staff' : role; }
const adminNav = [
  { label: 'Dashboard', href: '/admin/dashboard', key: 'dashboard', Icon: House },
  { label: 'Beneficiaries', href: '/admin/beneficiaries', key: 'beneficiaries', Icon: Users },
  { label: 'Programs', href: '/admin/programs', key: 'programs', Icon: Heart },
  { label: 'Events', href: '/admin/events', key: 'events', Icon: CalendarDays },
  { label: 'Volunteers', href: '/admin/volunteers', key: 'volunteers', Icon: HandHeart },
  { label: 'Users & roles', href: '/admin/users', key: 'users', Icon: ShieldCheck },
  { label: 'Reports', href: '/admin/reports', key: 'reports', Icon: ChartNoAxesCombined },
  { label: 'Settings', href: '/admin/settings', key: 'settings', Icon: Settings },
];
function readRole(): Role { try { const r = localStorage.getItem('pfp-demo-role'); return (r as Role) || 'Admin'; } catch { return 'Admin'; } }
function AdminShell({ children, section }: { children: ReactNode; section: string }) {
  const [role, setRole] = useState<Role>(readRole); const [mobile, setMobile] = useState(false); const [, setLocation] = useLocation();
  function logout() { localStorage.removeItem('pfp-demo-role'); setLocation('/admin/login'); }
  const nav = adminNav.filter(i => canAccessSection(role, i.key));
  return <div className="min-h-[100dvh] bg-[#f5f2ec] text-[#352a26] md:flex">
    <aside className={`fixed inset-y-0 left-0 z-40 flex w-[258px] flex-col bg-[#51261f] px-4 py-5 text-[#fff8ea] transition-transform md:sticky md:top-0 md:h-[100dvh] md:translate-x-0 ${mobile ? 'translate-x-0' : '-translate-x-full'}`}>
      <div className="flex items-center justify-between px-2"><Wordmark inverse/><button className="md:hidden" aria-label="Close menu" onClick={() => setMobile(false)}><X/></button></div>
      <div className="mt-9 px-3 text-[10px] font-bold uppercase tracking-[.2em] text-[#cbb4a0]">Workspace</div><nav className="mt-3 grid gap-1" aria-label="Admin navigation">{nav.map(item => { const Icon = item.Icon; return <Link key={item.key} onClick={() => setMobile(false)} href={item.href} className={`flex items-center gap-3 rounded-xl px-3 py-3 text-sm transition-colors ${section === item.key ? 'bg-[#75443a] text-white' : 'text-[#e0cfc0] hover:bg-[#63362d]'}`}><Icon size={17}/>{item.label}</Link>; })}</nav>
      <div className="mt-auto rounded-2xl border border-[#7c4d42] bg-[#5c3027] p-4"><div className="flex items-center gap-2 text-xs font-semibold"><span className="grid h-7 w-7 place-items-center rounded-full bg-[#d5dfcb] text-[#42563f]"><CircleUserRound size={16}/></span>{roleLabel(role)}</div><p className="mt-3 text-[11px] leading-5 text-[#e4d3c4]">Demo access only.<br/>No account or data sync.</p><button onClick={logout} className="mt-3 flex items-center gap-2 text-xs text-[#e9d8c8] hover:text-white"><LogOut size={14}/> Logout</button></div>
    </aside>
    {mobile && <button aria-label="Close navigation overlay" onClick={() => setMobile(false)} className="fixed inset-0 z-30 bg-[#2d1915]/40 md:hidden"/>}
    <div className="min-w-0 flex-1"><header className="sticky top-0 z-20 flex h-[72px] items-center justify-between border-b border-[#e6ded3] bg-[#f9f7f1]/95 px-4 backdrop-blur md:px-8"><div className="flex items-center gap-3"><button className="rounded-full p-2 hover:bg-[#eee8dd] md:hidden" onClick={() => setMobile(true)} aria-label="Open menu"><Menu/></button><span className="text-sm text-[#776b60]">People for Passion <span className="mx-2 text-[#c4b6a7]">/</span><b className="text-[#3f332e]">{adminNav.find(n => n.key === section)?.label || 'Workspace'}</b></span></div><div className="flex items-center gap-2"><span className="hidden rounded-full bg-[#e7ecdf] px-3 py-1.5 text-[11px] font-bold text-[#526348] sm:inline-flex">DEMO DATA</span><span className="grid h-9 w-9 place-items-center rounded-full bg-[#d9e2d2] text-[#4d6248]"><CircleUserRound size={19}/></span></div></header><main className="mx-auto max-w-[1440px] p-4 md:p-8">{canAccessSection(role, section) ? children : <div className="mx-auto mt-12 max-w-lg rounded-2xl border border-[#e8e1d7] bg-[#fffdf8] p-8 text-center"><ShieldCheck className="mx-auto text-[#7e9275]"/><h1 className="serif mt-4 text-3xl text-[#47271f]">This section is not in your demo role</h1><p className="mt-2 text-sm leading-6 text-[#796e63]">Your {roleLabel(role)} preview does not include this workspace area.</p><Button href="/admin/dashboard" className="mt-5">Return to overview</Button></div>}</main></div>
  </div>;
}
function AdminLogin() {
  const [, setLocation] = useLocation(); const [role, setRole] = useState<Role>('Admin'); const [show, setShow] = useState(false); const [notice,setNotice] = useState('');
  return <div className="grain flex min-h-[100dvh] items-center justify-center bg-[#efe8dc] px-5 py-10">
    <div className="grid w-full max-w-5xl overflow-hidden rounded-[2rem] bg-[#fbf8f2] shadow-[0_25px_90px_rgba(66,39,28,.15)] md:grid-cols-[1fr_1fr]">
      <div className="relative flex min-h-[260px] flex-col justify-between bg-[#51261f] p-8 text-[#fff8ea] md:p-12">
        <Wordmark inverse/>
        <div className="relative z-10 mt-14"><Eyebrow light>People for Passion — Administration</Eyebrow><h1 className="serif max-w-md text-4xl leading-tight md:text-5xl">A thoughtful space for the work behind the work.</h1><p className="mt-5 max-w-sm text-sm leading-7 text-[#e0cfc0]">Explore beneficiary workflows and staff tools using fictional demo records.</p></div>
        <p className="mt-10 text-xs text-[#cdb9a8]">Demo only. No account, authentication, password check or external data connection is used.</p>
        <div className="absolute -right-14 -top-8 h-52 w-52 rounded-full border border-[#8c6154] opacity-50"/><div className="absolute -bottom-20 right-12 h-64 w-64 rounded-full border border-[#8c6154] opacity-50"/>
      </div>
      <div className="p-8 md:p-12">
        <div className="mb-9 md:hidden"><Wordmark/></div><Eyebrow>Mock staff entry</Eyebrow><h2 className="serif text-4xl text-[#4d241e]">Enter the demo</h2>
        <p className="mt-3 text-sm leading-6 text-[#786b60]">Fields are for interface demonstration only. Any input is accepted and ignored; this is not real authentication.</p>
        {notice&&<p role="status" className="mt-4 rounded-xl bg-[#f1ece3] p-3 text-xs leading-5 text-[#695246]">{notice}</p>}
        <form onSubmit={e=>{e.preventDefault();localStorage.setItem('pfp-demo-role',role);setLocation('/admin/dashboard');}} className="mt-5 space-y-4">
          <label className="block text-sm font-semibold text-[#51473e]">Email or username<input autoComplete="username" type="text" className="mt-2 w-full rounded-xl border border-[#ded2c3] bg-white px-4 py-3 font-normal outline-none focus:border-primary" placeholder="Demo email or username"/></label>
          <label className="block text-sm font-semibold text-[#51473e]">Password<input autoComplete="current-password" type="password" className="mt-2 w-full rounded-xl border border-[#ded2c3] bg-white px-4 py-3 font-normal outline-none focus:border-primary" placeholder="Any demo-only text"/></label>
          <div className="flex items-center justify-between gap-2"><label className="inline-flex items-center gap-2 text-xs text-[#695e54]"><input type="checkbox" className="accent-[#6b4538]"/> Remember me</label><button type="button" onClick={()=>setNotice('Password recovery is not available in this mock demo. No password is checked or stored.')} className="text-xs font-semibold text-[#775b4b] underline underline-offset-4">Forgot password?</button></div>
          <label className="block text-sm font-semibold text-[#51473e]">Preview role<select value={role} onChange={e => setRole(e.target.value as Role)} className="mt-2 w-full rounded-xl border border-[#ded2c3] bg-white px-4 py-3 outline-none focus:border-primary">{(['Super Admin','Admin','Volunteer-Staff'] as Role[]).map(r => <option key={r} value={r}>{roleLabel(r)}</option>)}</select></label>
          <button type="button" onClick={() => setShow(v => !v)} className="text-xs font-semibold text-[#695246] underline underline-offset-4">{show ? 'Hide role permissions' : 'What can each role see?'}</button>
          {show && <div className="rounded-xl bg-[#f1ece3] p-4 text-xs leading-6 text-[#62554c]"><b>Super Admin</b>: all demo areas<br/><b>Admin</b>: beneficiaries, programs, events and reports<br/><b>Volunteer / Staff</b>: assigned beneficiaries, add and update records, and view programs</div>}
          <Button type="submit" className="w-full">Login to demo <ArrowRight size={16}/></Button>
        </form>
        <p className="mt-4 text-center text-xs leading-5 text-[#897a6e]">Mock flow only. Login does not verify, create or store credentials.</p><Link href="/" className="mt-6 flex items-center justify-center gap-2 text-sm text-[#70594a]"><ArrowLeft size={15}/> Return to public site</Link>
      </div>
    </div>
  </div>;
}
function DemoNotice() { return <div className="mb-6 flex items-start gap-3 rounded-2xl border border-[#ead9b6] bg-[#fff7e7] px-4 py-3 text-xs leading-5 text-[#73572e]"><CircleHelp size={17} className="mt-0.5 shrink-0"/><span><b>Demo workspace.</b> All figures and beneficiary records are fictional sample data for interface demonstration. They are not organizational impact claims.</span></div>; }
function PageHeading({ eyebrow, title, children, action }: { eyebrow: string; title: string; children?: ReactNode; action?: ReactNode }) {
  return <div className="mb-7 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p className="text-[10px] font-bold uppercase tracking-[.2em] text-[#8b6d5b]">{eyebrow}</p><h1 className="serif mt-2 text-4xl tracking-tight text-[#47271f] md:text-5xl">{title}</h1>{children && <p className="mt-2 max-w-2xl text-sm leading-6 text-[#796e63]">{children}</p>}</div>{action}</div>;
}
function Metric({ label, value, note, icon: Icon, tint }: { label: string; value: string; note: string; icon: typeof Users; tint: string }) {
  return <div className="rounded-2xl border border-[#e8e1d7] bg-[#fffdf8] p-5"><div className="flex items-start justify-between"><div><p className="text-xs font-medium text-[#776b60]">{label}</p><p className="serif mt-3 text-4xl text-[#3f3029]">{value}</p></div><span className={`grid h-10 w-10 place-items-center rounded-xl ${tint}`}><Icon size={19}/></span></div><p className="mt-3 text-[11px] text-[#897e73]">{note}</p></div>;
}
function AdminDashboard() {
  const [beneficiaries] = useState(() => { const records = readBeneficiaries(); return readRole() === 'Volunteer-Staff' ? records.filter(b => b.assignedTo === 'Volunteer-Staff') : records; });
  return <AdminShell section="dashboard"><DemoNotice/><PageHeading eyebrow="Your workspace" title="Welcome back, Admin" action={<span className="inline-flex items-center gap-2 text-xs text-[#756a60]"><CalendarDays size={15}/> Demo overview</span>}>Fictional example totals for the staff workspace. These are not real organization statistics.</PageHeading>
    <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric label="Total Beneficiaries" value="1,248" note="Fictional dashboard sample" icon={Users} tint="bg-[#f4e8dc] text-[#855143]"/><Metric label="Active Programs" value="8" note="Fictional dashboard sample" icon={HeartHandshake} tint="bg-[#e8eddf] text-[#5f7656]"/><Metric label="Upcoming Events" value="5" note="Fictional dashboard sample" icon={CalendarDays} tint="bg-[#f7edda] text-[#94723e]"/><Metric label="Volunteers" value="42" note="Fictional dashboard sample" icon={HandHeart} tint="bg-[#e8e5ed] text-[#6c617e]"/></div>
    <div className="mt-3 text-right text-[11px] text-[#897e73]">All dashboard values are fictional demo examples.</div>
    <div className="mt-6 grid gap-5 xl:grid-cols-[1.35fr_.65fr]"><section className="rounded-2xl border border-[#e8e1d7] bg-[#fffdf8] p-5 md:p-6"><div className="flex items-center justify-between"><div><h2 className="serif text-2xl text-[#47271f]">Recently Added Beneficiaries</h2><p className="mt-1 text-xs text-[#897e73]">Fictional local sample; not real case records</p></div><Button href="/admin/beneficiaries" tone="quiet" className="!px-3 !py-2">View all <ArrowRight size={15}/></Button></div><div className="mt-5 divide-y divide-[#eee8df]">{beneficiaries.slice(0,4).map(b => <Link href={`/admin/beneficiaries/${b.id}`} key={b.id} className="flex items-center justify-between gap-4 py-4"><div><p className="text-sm font-semibold text-[#473b34]">{b.name} <span className="ml-2 font-normal text-[#988b7f]">{b.id}</span></p><p className="mt-1 text-xs text-[#897e73]">{b.program} · {b.city}</p></div><StatusPill status={b.status}/></Link>)}</div></section>
      <section className="rounded-2xl border border-[#e8e1d7] bg-[#fffdf8] p-5 md:p-6"><Eyebrow>Quick actions</Eyebrow><h2 className="serif text-2xl text-[#47271f]">Make the next move.</h2><div className="mt-5 grid gap-3"><Button href="/admin/beneficiaries/new" className="justify-start"><Plus size={16}/> Add beneficiary</Button>{hasPermission(readRole(),'event.view')&&<Button href="/admin/events" tone="outline" className="justify-start"><CalendarDays size={16}/> Review events</Button>}{hasPermission(readRole(),'reports.view')&&<Button href="/admin/reports" tone="outline" className="justify-start"><ChartNoAxesCombined size={16}/> View demo reports</Button>}</div><div className="mt-6 rounded-xl bg-[#e9eee3] p-4 text-xs leading-5 text-[#56684f]">Use the sidebar to explore demo operations. Changes you make to beneficiary records stay in this browser.</div></section></div>
  </AdminShell>;
}
function StatusPill({ status }: { status: string }) {
  const color = status === 'Active' ? 'bg-[#e5efe1] text-[#4f6a49]' : status === 'Completed' ? 'bg-[#eae7e1] text-[#70685d]' : status === 'Pending' ? 'bg-[#f2e8e0] text-[#875342]' : 'bg-[#fff0d8] text-[#8a6634]';
  return <span className={`rounded-full px-3 py-1.5 text-[11px] font-semibold ${color}`}>{status}</span>;
}
const fields = ['id','phone','location'] as const;
