  const [all, setAll] = useState(readBeneficiaries); const existing = all.find(x=>x.id===id); const [record,setRecord] = useState<Omit<Beneficiary,'id'|'createdAt'>>(existing ? (({id:_id,createdAt:_date,...rest})=>rest)(existing) : emptyRecord);
