function BeneficiaryDetail() {
  const {id}=useParams<{id:string}>(); const role=readRole(); const [item,setItem]=useState(()=>readBeneficiaries().find(x=>x.id===id)); const [toast,setToast]=useState(''); const [followUpDate,setFollowUpDate]=useState('');
  useEffect(()=>{const next=readBeneficiaries().find(x=>x.id===id);setItem(next);setFollowUpDate(next?.followUp||'');},[id]);
  if(!item || (role==='Volunteer-Staff' && item.assignedTo!=='Volunteer-Staff')) return <AdminShell section="beneficiaries"><div className="rounded-2xl bg-white p-10 text-center"><h1 className="serif text-3xl">Record not found</h1><p className="mt-2 text-sm text-[#786b60]">This demo record is unavailable in your role or may have been removed.</p><Button href="/admin/beneficiaries" className="mt-5">Back to records</Button></div></AdminShell>;
  function update(status:string, followUp=item!.followUp) { const changed={...item!,status,followUp};const next=readBeneficiaries().map(x=>x.id===id?changed:x);writeBeneficiaries(next);setItem(changed);setFollowUpDate(followUp);setToast(status==='Completed'?'Case marked complete.':'Follow-up recorded.');setTimeout(()=>setToast(''),2800); }
  function addFollowUp() { if(!followUpDate){setToast('Choose a follow-up date first.');setTimeout(()=>setToast(''),2800);return;} update('Follow-up Required',followUpDate); }
  return <AdminShell section="beneficiaries"><DemoNotice/><PageHeading eyebrow={`Beneficiary · ${item.id}`} title={item.name} action={<div className="flex gap-2">{hasPermission(role,'beneficiary.edit')&&<Button href={`/admin/beneficiaries/${item.id}/edit`} tone="outline"><Pencil size={15}/> Edit</Button>}<Button href="/admin/beneficiaries"><ArrowLeft size={15}/> All cases</Button></div>}>Fictional demo profile. This record is stored only in this browser.</PageHeading>
    <div className="grid gap-5 xl:grid-cols-[1.25fr_.75fr]"><section className="space-y-5">
      <section className="rounded-2xl border border-[#e8e1d7] bg-[#fffdf8] p-6"><div className="flex items-start gap-4"><div className="grid h-16 w-16 shrink-0 place-items-center rounded-full bg-[#e7ece1] text-[#64795d]"><CircleUserRound size={34}/></div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><h2 className="serif text-3xl text-[#47271f]">{item.name}</h2><StatusPill status={item.status}/></div><p className="mt-1 text-sm text-[#897e73]">{item.id} · {item.age} years · {item.gender}</p><p className="mt-1 text-[11px] text-[#897e73]">Profile image not provided · fictional demo record</p></div></div>
        <div className="mt-7 border-t border-[#eee8df] pt-6"><h3 className="text-xs font-bold uppercase tracking-[.15em] text-[#8a7d71]">Personal information</h3><div className="mt-4 grid gap-5 sm:grid-cols-2"><DetailField label="Date of birth" value={item.dob||'Not provided'}/><DetailField label="Age" value={`${item.age} years`}/><DetailField label="Gender" value={item.gender||'Not provided'}/></div></div>
        <div className="mt-6 border-t border-[#eee8df] pt-6"><h3 className="text-xs font-bold uppercase tracking-[.15em] text-[#8a7d71]">Contact information</h3><div className="mt-4 grid gap-5 sm:grid-cols-2"><DetailField label="Phone" value={item.phone}/><DetailField label="Email" value={item.email||'Not provided'}/></div></div>
        <div className="mt-6 border-t border-[#eee8df] pt-6"><h3 className="text-xs font-bold uppercase tracking-[.15em] text-[#8a7d71]">Address</h3><p className="mt-2 text-sm leading-6 text-[#4d433b]">{[item.address,item.city,item.state,item.pin].filter(Boolean).join(', ')||'Not provided'}</p></div>
      </section>
      <section className="rounded-2xl border border-[#e8e1d7] bg-[#fffdf8] p-6"><h2 className="serif text-2xl text-[#47271f]">Support information</h2><div className="mt-5 grid gap-5 sm:grid-cols-2"><DetailField label="Category" value={item.category}/><DetailField label="Program" value={item.program}/><DetailField label="Type of support" value={item.supportType||'Not provided'}/><DetailField label="Priority" value={item.priority}/></div></section>
      <section className="rounded-2xl border border-[#e8e1d7] bg-[#fffdf8] p-6"><h2 className="serif text-2xl text-[#47271f]">Program history</h2><div className="mt-4 border-l-2 border-[#d4dfcc] pl-4"><p className="text-sm font-semibold text-[#51473e]">{item.program}</p><p className="mt-1 text-xs text-[#897e73]">{item.category} · dates and further history not provided</p></div></section>
      <section className="rounded-2xl border border-[#e8e1d7] bg-[#fffdf8] p-6"><h2 className="serif text-2xl text-[#47271f]">Notes</h2><p className="mt-3 whitespace-pre-wrap text-sm leading-6 text-[#62554c]">{item.notes||'No notes added.'}</p></section>
      <section className="rounded-2xl border border-[#e8e1d7] bg-[#fffdf8] p-6"><h2 className="serif text-2xl text-[#47271f]">Activity timeline</h2><p className="mt-1 text-xs text-[#897e73]">Fictional workflow preview based on this local demo record.</p><ol className="mt-5 space-y-4 border-l-2 border-[#d4dfcc] pl-5"><li><p className="text-sm font-semibold text-[#51473e]">Registered</p><p className="mt-1 text-xs text-[#897e73]">{item.createdAt}</p></li><li><p className="text-sm font-semibold text-[#51473e]">Support Provided</p><p className="mt-1 text-xs text-[#897e73]">Demo workflow step · no service date recorded</p></li><li><p className="text-sm font-semibold text-[#51473e]">Follow-up</p><p className="mt-1 text-xs text-[#897e73]">{item.followUp||'Not scheduled'}</p></li><li><p className="text-sm font-semibold text-[#51473e]">Case Completed</p><p className="mt-1 text-xs text-[#897e73]">{item.status==='Completed'?'Completed':'Not completed'}</p></li></ol></section>
    </section><aside className="space-y-5"><section className="rounded-2xl border border-[#e8e1d7] bg-[#fffdf8] p-6"><Eyebrow>Case actions</Eyebrow><h2 className="serif text-2xl text-[#47271f]">Keep care moving.</h2><label className="mt-5 block text-xs font-semibold text-[#5d5147]">Follow-up date<input aria-label="Follow-up date" type="date" value={followUpDate} onChange={e=>setFollowUpDate(e.target.value)} className="mt-2 w-full rounded-xl border border-[#dfd7cc] bg-[#fffefa] px-3.5 py-2.5 text-sm outline-none focus:border-primary"/></label><Button className="mt-3 w-full justify-start" onClick={addFollowUp}><CalendarDays size={16}/> Add Follow-up</Button><Button className="mt-2 w-full justify-start" tone="outline" disabled={item.status==='Completed'} onClick={()=>update('Completed')}><BadgeCheck size={16}/> Mark as Completed</Button><p className="mt-4 text-xs leading-5 text-[#897e73]">Actions update this fictional record in local browser storage.</p></section><section className="rounded-2xl bg-[#e9eee3] p-6"><Eyebrow>Next follow-up</Eyebrow><p className="serif text-2xl text-[#354737]">{item.followUp||'Not scheduled'}</p><p className="mt-2 text-xs text-[#66755e]">Demo date · created {item.createdAt}</p></section></aside></div>{toast&&<div role="status" className="fixed bottom-5 right-5 z-50 rounded-xl bg-[#394b38] px-5 py-3 text-sm text-white shadow-lg">{toast}</div>}</AdminShell>;
}
function DetailField({label,value}:{label:string;value:string}) { return <div><p className="text-[10px] font-bold uppercase tracking-[.14em] text-[#97887b]">{label}</p><p className="mt-1.5 whitespace-pre-wrap text-sm leading-6 text-[#4d433b]">{value}</p></div>; }
function AdminCollection({ section, title, description }: { section:string; title:string; description:string }) {
  const fallback = section==='programs'?initiativeGroups.flatMap(x=>x.items):section==='events'?publicEvents.map(x=>x.title):section==='volunteers'?['Volunteer roster · demo','Community support · demo']:section==='users'?['Role access overview']:section==='reports'?['Beneficiary status summary','Program overview']:['Workspace preferences'];
  const [items,setItems]=useState<string[]>(()=>readDemoCollection(section,fallback));
  const [toast,setToast]=useState('');const [show,setShow]=useState(false);const [value,setValue]=useState('');
  const role = readRole(); const addPermission: Partial<Record<string, Permission>> = { programs: 'program.create', events: 'event.create', volunteers: 'volunteer.manage' }; const canAdd = addPermission[section] ? hasPermission(role, addPermission[section]!) : false;
  const icons:Record<string,typeof Heart>={programs:Heart,events:CalendarDays,volunteers:HandHeart,users:ShieldCheck,reports:ChartNoAxesCombined,settings:Settings};const Icon=icons[section]||FileText;
  function add(){if(!value.trim())return;setItems(old=>{const next=[value.trim(),...old];writeDemoCollection(section,next);return next;});setValue('');setShow(false);setToast('Demo item saved in this browser.');setTimeout(()=>setToast(''),2500);}
  return <AdminShell section={section}><DemoNotice/><PageHeading eyebrow={`Workspace · Demo ${title.toLowerCase()}`} title={title} action={canAdd?<Button onClick={()=>setShow(v=>!v)}><Plus size={16}/> Add {title.replace(/s$/,'').toLowerCase()}</Button>:undefined}>{description}</PageHeading>
    {show&&<div className="mb-5 rounded-2xl border border-[#e6ded3] bg-[#fffdf8] p-5"><label className="block text-xs font-semibold text-[#5d5147]">New demo item<input autoFocus value={value} onChange={e=>setValue(e.target.value)} onKeyDown={e=>{if(e.key==='Enter')add();}} className="mt-2 w-full rounded-xl border border-[#dfd7cc] bg-white px-4 py-3 text-sm outline-none focus:border-primary" placeholder={`Name this ${title.toLowerCase().replace(/s$/,'')}`}/></label><div className="mt-3 flex justify-end gap-2"><Button tone="outline" onClick={()=>setShow(false)}>Cancel</Button><Button onClick={add}>Add item <Check size={15}/></Button></div></div>}
    {section==='reports'&&<div className="mb-5 grid gap-4 md:grid-cols-3"><Metric label="Cases in sample" value={String(readBeneficiaries().length)} note="Fictional dataset" icon={Users} tint="bg-[#f4e8dc] text-[#855143]"/><Metric label="Active" value={String(readBeneficiaries().filter(x=>x.status==='Active').length)} note="Sample case status" icon={Activity} tint="bg-[#e8eddf] text-[#5f7656]"/><Metric label="Completed" value={String(readBeneficiaries().filter(x=>x.status==='Completed').length)} note="Sample case status" icon={BadgeCheck} tint="bg-[#f7edda] text-[#94723e]"/></div>}
    {section==='settings'&&<div className="mb-5 rounded-2xl border border-[#e8e1d7] bg-[#fffdf8] p-5"><h2 className="serif text-2xl text-[#47271f]">Demo preferences</h2><p className="mt-2 text-sm leading-6 text-[#796e63]">Local-only workspace preferences. Public site content and backend settings are not connected here.</p><label className="mt-5 flex items-center justify-between rounded-xl bg-[#f5f1e9] p-4 text-sm text-[#51473e]">Show fictional demo dataset <input type="checkbox" defaultChecked className="h-4 w-4 accent-[#6b4538]"/></label><p className="mt-3 text-xs text-[#897e73]">Beneficiary edits are stored in browser localStorage.</p></div>}
    {section==='users'&&<div className="mb-5 rounded-2xl border border-[#e8e1d7] bg-[#fffdf8] p-5"><h2 className="serif text-2xl text-[#47271f]">Role-aware demo access</h2><p className="mt-2 text-sm text-[#796e63]">Select a mock role on the admin login screen. No real users or authentication exist.</p><div className="mt-4 grid gap-3 md:grid-cols-3">{Object.entries(permissionMap).map(([role,perms])=><div key={role} className="rounded-xl bg-[#f5f1e9] p-4"><p className="text-sm font-semibold">{roleLabel(role as Role)}</p><p className="mt-2 text-xs leading-5 text-[#897e73]">{perms.join(' · ')}</p></div>)}</div></div>}
    <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">{items.map((name,i)=>{const metadata=allInitiatives.find(entry=>entry.title===name);return <article key={`${name}-${i}`} className="rounded-2xl border border-[#e8e1d7] bg-[#fffdf8] p-4">{(section==='programs'||section==='events')&&<InitiativeArt title={name} category={metadata?.category||'Community'} index={i}/>}<div className="mt-4 flex items-start justify-between"><span className="grid h-10 w-10 place-items-center rounded-xl bg-[#e9eee3] text-[#617656]"><Icon size={19}/></span><span className="rounded-full bg-[#f1ece3] px-2.5 py-1 text-[10px] font-bold text-[#817365]">DEMO</span></div><h2 className="serif mt-4 text-xl text-[#47271f]">{name}</h2><p className="mt-2 text-xs leading-5 text-[#897e73]">{section==='programs'?'Initiative from the verified list.':section==='events'?'Event details are not confirmed.':section==='volunteers'?'Roster controls are illustrative; no real volunteer records.':section==='reports'?'Summary based on fictional beneficiary records.':section==='settings'?'Local demo workspace preferences.':'Mock role configuration.'}</p><div className="mt-4 space-y-1 rounded-xl bg-[#f7f3ec] p-3 text-[11px] leading-5 text-[#796e63]"><p>Category · {metadata?.category||'Details to be confirmed'}</p><p>Date · Details to be confirmed</p><p>Location · Details to be confirmed</p><p>Status · Details to be confirmed</p><p>Details · Details to be confirmed</p></div><div className="mt-4 flex items-center justify-between border-t border-[#eee8df] pt-4 text-[11px] text-[#897e73]"><span>{section==='programs'?'Program':section==='events'?'Details to be confirmed':section==='reports'?'Fictional data':'Demo view'}</span>{section==='events'&&<Link href="/events" className="inline-flex items-center gap-1 font-semibold text-primary">Public archive <ArrowRight size={13}/></Link>}</div></article>;})}</div>{toast&&<div role="status" className="fixed bottom-5 right-5 z-50 rounded-xl bg-[#394b38] px-5 py-3 text-sm text-white shadow-lg">{toast}</div>}
  </AdminShell>;
}
function Router() {
  return <RoutedErrorBoundary><Switch>
    <Route path="/" component={HomePage}/><Route path="/about" component={AboutPage}/><Route path="/programs" component={ProgramsPage}/><Route path="/events" component={EventsPage}/><Route path="/events/:id" component={EventDetailPage}/><Route path="/contact" component={ContactPage}/>
    <Route path="/admin/login" component={AdminLogin}/><Route path="/admin/dashboard" component={AdminDashboard}/><Route path="/admin/beneficiaries" component={BeneficiaryList}/><Route path="/admin/beneficiaries/new" component={()=> <BeneficiaryForm/>}/><Route path="/admin/beneficiaries/:id/edit" component={()=> <BeneficiaryForm edit/>}/><Route path="/admin/beneficiaries/:id" component={BeneficiaryDetail}/>
    <Route path="/admin/programs" component={()=> <AdminCollection section="programs" title="Programs" description="Explore the verified initiative list. Demo additions are stored in this browser."/>}/><Route path="/admin/events" component={()=> <AdminCollection section="events" title="Events" description="Review listed initiatives; dates and locations remain unconfirmed where no details were provided."/>}/><Route path="/admin/volunteers" component={()=> <AdminCollection section="volunteers" title="Volunteers" description="A useful preview of volunteer coordination. No real volunteer roster or personal data is connected."/>}/><Route path="/admin/users" component={()=> <AdminCollection section="users" title="Users & roles" description="Review the mock role permission model used by this demo workspace."/>}/><Route path="/admin/reports" component={()=> <AdminCollection section="reports" title="Reports" description="Operational summaries use fictional local sample records only."/>}/><Route path="/admin/settings" component={()=> <AdminCollection section="settings" title="Settings" description="Demo workspace preferences and local data notes."/>}/>
    <Route component={NotFound}/>
  </Switch></RoutedErrorBoundary>;
}
function RoutedErrorBoundary({ children }: { children: ReactNode }) {
  const [location] = useLocation();
  return <ErrorBoundary resetKey={location}>{children}</ErrorBoundary>;
}
function App() {
  return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><Router/></WouterRouter><Toaster/></TooltipProvider></QueryClientProvider>;
}
export default App;